import httpx


def make_client(transport: httpx.BaseTransport) -> httpx.Client:
    return httpx.Client(transport=transport, trust_env=False,
                        headers={"X-App": "PatchPilot"})

import httpx

from .client import make_client


def fetch_profile(transport: httpx.BaseTransport, user_id: int) -> str:
    with make_client(transport) as client:
        response = client.get(f"https://example.invalid/users/{user_id}")
        return str(response.json()["name"]).strip()
